import{_ as l,a0 as o,w as h,s as d,ao as p,I as t,a1 as e,A as n,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 上查找硬件規格 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上查找硬件規格 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上查找硬件規格 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上查找硬件規格 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190805 How To Find Hardware Specifications On Linux","title":"如何在 Linux 上查找硬件規格","tag":"201908","desc":""},"relativePath":"201908/20190805 How To Find Hardware Specifications On Linux.md","filePath":"[post].md"}'),r={name:"201908/20190805 How To Find Hardware Specifications On Linux.md"};function c(g,s,u,k,b,f){const a=o("Link");return h(),d("div",null,[s[19]||(s[19]=p(`<h1 id="如何在-linux-上查找硬件規格" tabindex="-1">如何在 Linux 上查找硬件規格 <a class="header-anchor" href="#如何在-linux-上查找硬件規格" aria-label="Permalink to “如何在 Linux 上查找硬件規格”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201908/06/111717t1f77n7v3egxhf18.jpg" alt=""></p><p>在 Linux 系統上有許多工具可用於查找硬件規格。在這裏，我列出了四種最常用的工具，可以獲取 Linux 系統的幾乎所有硬件（和軟件）細節。好在是這些工具在某些 Linux 發行版上默認預裝。我在 Ubuntu 18.04 LTS 桌面上測試了這些工具，但是它們也適用於其他 Linux 發行版。</p><h3 id="_1、lshw" tabindex="-1">1、LSHW <a class="header-anchor" href="#_1、lshw" aria-label="Permalink to “1、LSHW”">​</a></h3><p>lshw（硬件列表）是一個簡單但功能齊全的實用程序，它提供了 Linux 系統上的硬件規格的詳細信息。它可以報告確切的內存規格、固件版本、主板規格、CPU 版本和速度、緩存規格、總線速度等。信息可以以純文本、XML 或 HTML 格式輸出。</p><p>它目前支持 DMI（僅限 x86 和 EFI）、Open Firmware 設備樹（僅限 PowerPC）、PCI/AGP、ISA PnP（x86）、CPUID（x86）、IDE/ATA/ATAPI、PCMCIA（僅在 x86 上測試過）、USB 和 SCSI。</p><p>就像我已經説過的那樣，Ubuntu 默認預裝了 lshw。如果它未安裝在你的 Ubuntu 系統中，請使用以下命令安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install lshw lshw-gtk</span></span></code></pre></div><p>在其他 Linux 發行版上，例如 Arch Linux，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S lshw lshw-gtk</span></span></code></pre></div><p>安裝後，運行 <code>lshw</code> 以查找系統硬件詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw</span></span></code></pre></div><p>你將看到輸出詳細的系統硬件。</p><p>示例輸出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-using-lshw-1.png" alt=""></p><p><em>使用 lshw 在 Linux 上查找硬件規格</em></p><p>請注意，如果你沒有以 <code>sudo</code> 權限運行 <code>lshw</code> 命令，則輸出可能不完整或不準確。</p><p><code>lshw</code> 可以將輸出顯示為 HTML 頁面。為此，請使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -html</span></span></code></pre></div><p>同樣，我們可以將設備樹輸出為 XML 和 json 格式，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -xml</span></span>
<span class="line"><span>$ sudo lshw -json</span></span></code></pre></div><p>要輸出顯示硬件路徑的設備樹，請使用 <code>-short</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -short</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Show-device-tree-with-hardware-path-using-lshw.png" alt=""></p><p><em>使用 lshw 顯示具有硬件路徑的設備樹</em></p><p>要列出設備的總線信息、詳細的 SCSI、USB、IDE 和 PCI 地址，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -businfo</span></span></code></pre></div><p>默認情況下，<code>lshw</code> 顯示所有硬件詳細信息。你還可以使用類選項查看特定硬件詳細信息的硬件信息，例如處理器、內存、顯示器等。可以使用 <code>lshw -short</code> 或 <code>lshw -businfo</code> 找到類選項。</p><p>要顯示特定硬件詳細信息，例如處理器，請執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class processor</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*-cpu</span></span>
<span class="line"><span>description: CPU</span></span>
<span class="line"><span>product: Intel(R) Core(TM) i3-2350M CPU @ 2.30GHz</span></span>
<span class="line"><span>vendor: Intel Corp.</span></span>
<span class="line"><span>physical id: 4</span></span>
<span class="line"><span>bus info: [email protected]</span></span>
<span class="line"><span>version: Intel(R) Core(TM) i3-2350M CPU @ 2.30GHz</span></span>
<span class="line"><span>serial: To Be Filled By O.E.M.</span></span>
<span class="line"><span>slot: CPU 1</span></span>
<span class="line"><span>size: 913MHz</span></span>
<span class="line"><span>capacity: 2300MHz</span></span>
<span class="line"><span>width: 64 bits</span></span>
<span class="line"><span>clock: 100MHz</span></span>
<span class="line"><span>capabilities: x86-64 fpu fpu_exception wp vme de pse tsc msr pae mce cx8 apic sep mtrr pge mca cmov pat pse36 clflush dts acpi mmx fxsr sse sse2 ss ht tm pbe syscall nx rdtscp constant_tsc arch_perfmon pebs bts rep_good nopl xtopology nonstop_tsc cpuid aperfmperf pni pclmulqdq dtes64 monitor ds_cpl vmx est tm2 ssse3 cx16 xtpr pdcm pcid sse4_1 sse4_2 x2apic popcnt tsc_deadline_timer xsave avx lahf_lm epb pti ssbd ibrs ibpb stibp tpr_shadow vnmi flexpriority ept vpid xsaveopt dtherm arat pln pts md_clear flush_l1d cpufreq</span></span>
<span class="line"><span>configuration: cores=2 enabledcores=1 threads=2</span></span></code></pre></div><p>類似的，你可以得到系統細節：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class system</span></span></code></pre></div><p>硬盤細節：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class disk</span></span></code></pre></div><p>網絡細節：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class network</span></span></code></pre></div><p>內存細節：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class memory</span></span></code></pre></div><p>你也可以像下面這樣列出多個設備的細節：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class storage -class power -class volume</span></span></code></pre></div><p>如果你想要查看帶有硬件路徑的細節信息，加上 <code>-short</code> 選項即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -short -class processor</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>H/W path Device Class Description</span></span>
<span class="line"><span>=======================================================</span></span>
<span class="line"><span>/0/4 processor Intel(R) Core(TM) i3-2350M CPU @ 2.30GHz</span></span></code></pre></div><p>有時，你可能希望將某些硬件詳細信息共享給別人，例如客户支持人員。如果是這樣，你可以從輸出中刪除潛在的敏感信息，如 IP 地址、序列號等，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lshw -sanitize</span></span></code></pre></div><h4 id="lshw-gtk-gui-工具" tabindex="-1">lshw-gtk GUI 工具 <a class="header-anchor" href="#lshw-gtk-gui-工具" aria-label="Permalink to “lshw-gtk GUI 工具”">​</a></h4><p>如果你對 CLI 不熟悉，可以使用 <code>lshw-gtk</code>，這是 <code>lshw</code> 命令列工具的圖形界面。</p><p>它可以從終端或 Dash 中打開。</p><p>要從終端啓動它，只需執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw-gtk</span></span></code></pre></div><p>這是 <code>lshw</code> 工具的默認 GUI 界面。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-using-lshw-gtk-1.png" alt=""></p><p><em>使用 lshw-gtk 在 Linux 上查找硬件</em></p><p>只需雙擊“Portable Computer”即可進一步展開細節。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-using-lshw-gtk-2.png" alt=""></p><p><em>使用 lshw-gtk GUI 在 Linux 上查找硬件</em></p><p>你可以雙擊後續的硬件選項卡以獲取詳細視圖。</p><p>有關更多詳細信息，請參閲手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man lshw</span></span></code></pre></div><h3 id="_2、inxi" tabindex="-1">2、Inxi <a class="header-anchor" href="#_2、inxi" aria-label="Permalink to “2、Inxi”">​</a></h3><p>Inxi 是我查找 Linux 系統上幾乎所有內容的另一個最喜歡的工具。它是一個自由開源的、功能齊全的命令列系統信息工具。它顯示了系統硬件、CPU、驅動程序、Xorg、桌面、內核、GCC 版本、進程、RAM 使用情況以及各種其他有用信息。無論是硬盤還是 CPU、主板還是整個系統的完整細節，inxi 都能在幾秒鐘內更準確地顯示它。由於它是 CLI 工具，你可以在桌面或服務器版本中使用它。有關更多詳細信息，請參閲以下指南。</p>`,64)),t("ul",null,[t("li",null,[e(a,{href:"https://www.ostechnix.com/how-to-find-your-system-details-using-inxi/"},{default:n(()=>[...s[0]||(s[0]=[i("如何使用 inxi 發現系統細節",-1)])]),_:1})])]),s[20]||(s[20]=p('<h3 id="_3、hardinfo" tabindex="-1">3、Hardinfo <a class="header-anchor" href="#_3、hardinfo" aria-label="Permalink to “3、Hardinfo”">​</a></h3><p>Hardinfo 將為你提供 <code>lshw</code> 中沒有的系統硬件和軟件詳細信息。</p><p>HardInfo 可以收集有關係統硬件和操作系統的信息，執行基準測試，並以 HTML 或純文本格式生成可打印的報告。</p><p>如果 Ubuntu 中未安裝 Hardinfo，請使用以下命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install hardinfo</span></span></code></pre></div><p>安裝後，Hardinfo 工具可以從終端或菜單中進行。</p><p>以下是 Hardinfo 默認界面的外觀。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-Using-Hardinfo.png" alt=""></p><p><em>使用 Hardinfo 在 Linux 上查找硬件</em></p><p>正如你在上面的屏幕截圖中看到的，Hardinfo 的 GUI 簡單直觀。</p><p>所有硬件信息分為四個主要組：計算機、設備、網絡和基準。每個組都顯示特定的硬件詳細信息。</p><p>例如，要查看處理器詳細信息，請單擊“設備”組下的“處理器”選項。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Show-processor-details-using-hardinfo.png" alt=""></p><p><em>使用 hardinfo 顯示處理器詳細信息</em></p><p>與 <code>lshw</code> 不同，Hardinfo 可幫助你查找基本軟件規範，如操作系統詳細信息、內核模組、區域設置信息、文件系統使用情況、用户/組和開發工具等。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Show-operating-system-details-using-hardinfo.png" alt=""></p><p><em>使用 hardinfo 顯示操作系統詳細信息</em></p><p>Hardinfo 的另一個顯着特點是它允許我們做簡單的基準測試來測試 CPU 和 FPU 功能以及一些圖形用户界面功能。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Perform-benchmarks-using-hardinfo.png" alt=""></p><p><em>使用 hardinfo 執行基準測試</em></p><p>建議閲讀：</p>',21)),t("ul",null,[t("li",null,[e(a,{href:"https://www.ostechnix.com/phoronix-test-suite-open-source-testing-benchmarking-tool/"},{default:n(()=>[...s[1]||(s[1]=[i("Phoronix 測試套件 - 開源測試和基準測試工具",-1)])]),_:1})]),t("li",null,[e(a,{href:"https://www.ostechnix.com/unixbench-benchmark-suite-unix-like-systems/"},{default:n(()=>[...s[2]||(s[2]=[i("UnixBench - 類 Unix 系統的基準套件",-1)])]),_:1})]),t("li",null,[e(a,{href:"https://www.ostechnix.com/how-to-benchmark-linux-commands-and-programs-from-commandline/"},{default:n(()=>[...s[3]||(s[3]=[i("如何從命令列對 Linux 命令和程序進行基準測試",-1)])]),_:1})])]),s[21]||(s[21]=p('<p>我們可以生成整個系統以及各個設備的報告。要生成報告，只需單擊菜單欄上的“生成報告”按鈕，然後選擇要包含在報告中的信息。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Generate-system-reports-using-hardinfo.png" alt=""></p><p><em>使用 hardinfo 生成系統報告</em></p><p>Hardinfo 也有幾個命令列選項。</p><p>例如，要生成報告並在終端中顯示它，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hardinfo -r</span></span></code></pre></div><p>列出模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hardinfo -l</span></span></code></pre></div><p>更多信息請參考手冊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man hardinfo</span></span></code></pre></div><h3 id="_4、sysinfo" tabindex="-1">4、Sysinfo <a class="header-anchor" href="#_4、sysinfo" aria-label="Permalink to “4、Sysinfo”">​</a></h3><p>Sysinfo 是 HardInfo 和 lshw-gtk 實用程序的另一個替代品，可用於獲取下面列出的硬件和軟件信息。</p><ul><li>系統詳細信息，如發行版版本、GNOME 版本、內核、gcc 和 Xorg 以及主機名。</li><li>CPU 詳細信息，如供應商標識、型號名稱、頻率、L2 緩存、型號和標誌。</li><li>內存詳細信息，如系統全部內存、可用內存、交換空間總量和空閒、緩存、活動/非活動的內存。</li><li>存儲控制器，如 IDE 接口、所有 IDE 設備、SCSI 設備。</li><li>硬件詳細信息，如主板、圖形卡、聲卡和網絡設備。</li></ul><p>讓我們使用以下命令安裝 sysinfo：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install sysinfo</span></span></code></pre></div><p>Sysinfo 可以從終端或 Dash 啓動。</p><p>要從終端啓動它，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sysinfo</span></span></code></pre></div><p>這是 Sysinfo 實用程序的默認界面。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/sysinfo-interface.png" alt=""></p><p><em>sysinfo 界面</em></p><p>如你所見，所有硬件（和軟件）詳細信息都分為五類，即系統、CPU、內存、存儲和硬件。單擊導航欄上的類別以獲取相應的詳細信息。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-Using-Sysinfo.png" alt=""></p><p><em>使用 Sysinfo 在 Linux 上查找硬件</em></p><p>更多細節可以在手冊頁上找到。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man sysinfo</span></span></code></pre></div><p>就這樣。就像我已經提到的那樣，可以有很多工具可用於顯示硬件/軟件規範。但是，這四個工具足以找到你的 Linux 發行版的所有軟硬件規格信息。</p><hr>',28)),t("p",null,[s[5]||(s[5]=i("via: ",-1)),e(a,{href:"https://www.ostechnix.com/getting-hardwaresoftware-specifications-in-linux-mint-ubuntu/"},{default:n(()=>[...s[4]||(s[4]=[i("https://www.ostechnix.com/getting-hardwaresoftware-specifications-in-linux-mint-ubuntu/",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=i("作者：",-1)),e(a,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...s[6]||(s[6]=[i("sk",-1)])]),_:1}),s[11]||(s[11]=i(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[7]||(s[7]=[i("lujun9972",-1)])]),_:1}),s[12]||(s[12]=i(" 譯者：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1}),s[13]||(s[13]=i(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[9]||(s[9]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[14]||(s[14]=[i("LCTT",-1)])]),_:1}),s[17]||(s[17]=i(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[15]||(s[15]=[i("Linux中國",-1)])]),_:1}),s[18]||(s[18]=i(" 榮譽推出",-1))])])}const y=l(r,[["render",c]]);export{x as __pageData,y as default};
